void TIM4_IRQHandler(void) {
	//Status register
	uint32_t* TIM4_SR = (uint32_t*)(0x40000800 + 0x10);
	uint32_t* GPIOB_CURR = (uint32_t*)(0x48000400 + 0x14);
	uint32_t* GPIOC_CURR = (uint32_t*)(0x48000800 + 0x14);

	if ((*TIM4_SR & (1U << 0))) {
		//set bit 0 to 0, otherwise its changed by the hardware
		*TIM4_SR &= ~(1U << 0);

		if (toggle == 0) { //if off do the cycle
			//turn them off
			*GPIOB_CURR &= ~(1U << 14);
			*GPIOB_CURR &= ~(1U << 7);
			*GPIOC_CURR &= ~(1U << 7);


			//cycle through the colors-move through them
			color = (color + 1) % 3;

			if (color == 1) {
				*GPIOC_CURR |= (1U << 7); //turn on green

			} else if (color == 2) {
				*GPIOB_CURR |= (1U << 7); //turn on blue
			} else {
				*GPIOB_CURR |= (1U << 14); //turn on red
			}
		}


	}
}

void EXTI15_10_IRQHandler(void) {
	//reset the pending register
	uint32_t EXTI_PR1 = 0x40010400;
	uint32_t EXTI_PR1_OFFSET = 0x14;
	uint32_t* PR1 = (uint32_t*)(EXTI_PR1 + EXTI_PR1_OFFSET);
	uint32_t* GPIOC_IDR = (uint32_t*)(0x48000800 + 0x10); //TO SEE THE INPUT DATA

	//what to do when the interrupt happens
	//need to clear the pending flag
	if (*PR1 & (1U << 13) ) {
		//RESET THE PENDING REGISTER
		*PR1 = (1U << 13);

		//checks if PC13 (pin 13/bit 13) is high or equal to 1, which would be the button is pressed
		if (*GPIOC_IDR & (1U << 13)) {
			//toggle the blue led
			toggle = 1; //pressed

		} else {
			toggle = 0; //not pressed
		}
	}



}








